package com.jnapanam.sportszone.notification.model;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="notification_templates")public class NotificationTemplate{@Id private UUID id;@Column(nullable=false,unique=true,length=60)private String code;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private NotificationChannel channel;@Column(length=180)private String subject;@Column(nullable=false,columnDefinition="TEXT")private String body;@Column(nullable=false)private boolean active;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected NotificationTemplate(){}public NotificationTemplate(String c,NotificationChannel ch,String s,String b){id=UUID.randomUUID();code=c.trim().toUpperCase(Locale.ROOT);channel=ch;subject=clean(s);body=b.trim();active=true;createdAt=Instant.now();updatedAt=createdAt;}public void update(NotificationChannel ch,String s,String b,boolean a){channel=ch;subject=clean(s);body=b.trim();active=a;updatedAt=Instant.now();}public UUID getId(){return id;}public String getCode(){return code;}public NotificationChannel getChannel(){return channel;}public String getSubject(){return subject;}public String getBody(){return body;}public boolean isActive(){return active;}private static String clean(String v){return v==null||v.isBlank()?null:v.trim();}}
